// ═══════════════════════════════════════════════════════════════════════
//  THE ONLY NODE YOU EDIT. One { … } block per sender domain you care about.
// ═══════════════════════════════════════════════════════════════════════
//
//  domain    REQUIRED. Sender domain, e.g. 'ostimteknik.edu.tr'. Subdomains
//            count (ogrenci@mail.ostimteknik.edu.tr); lookalikes do not
//            (info@ostimteknik.edu.tr.example.com). Igor checks the From
//            header properly rather than trusting a substring match.
//
//  agent     Optional, default 'ultron'. Who reads the mail and writes the
//            push. Ultron owns academic life, so university mail is his by
//            default — 'speda' for anything that isn't really about study.
//
//  intent    Optional. What the agent should DO with it. The mail body is
//            already in the payload either way, so the agent never re-fetches.
//            Leave empty for the sensible default below.
//
//  unread    Optional, default false. Only consider unread mail. Leave false:
//            reading a mail on your phone should not stop the push, the
//            category is what tracks 'handled'.
//
//  folder    Optional. Well-known name ('inbox') or a folder id, when the
//            university's mail is auto-filed. Empty = the whole mailbox,
//            which is the safe default — a rule that only watches the inbox
//            goes silent the day an Outlook rule starts filing that sender.
//
//  category  Optional, default 'SPEDA-Seen'. The Outlook category that marks
//            a message handled. Give a rule its OWN category only if two
//            rules could match the SAME message.
//
//  max       Optional, default 10, cap 25. Messages per scan.
//
const DOMAINS = [

  {
    domain: 'ostimteknik.edu.tr',
    agent: 'ultron',
    intent: '',
  },

  // { domain: 'obs.ostimteknik.edu.tr', agent: 'ultron',
  //   intent: 'Bu bir öğrenci bilgi sistemi bildirimi. Not, devamsızlık veya kayıt değişikliği varsa net söyle.' },

];

// ── Nothing below this line needs editing ───────────────────────────────
const DEFAULT_INTENT = "New mail arrived in the owner's UNIVERSITY mailbox (Microsoft 365). The sender, subject and body of every message are ALREADY in `messages` in this payload — do NOT call Outlook or load a toolset, you have the mail. Read it and write the owner one short push in their language: who wrote, what they actually want, and any deadline, exam date, room change, fee or action required. One line per message if several arrived. If something needs a reply or a date on the calendar, say so plainly and offer to do it — do not do it unasked.";

const out = [];
DOMAINS.forEach((m, i) => {
  if (!m || !m.domain) { return; }
  out.push({
    json: {
      domain: String(m.domain).trim().replace(/^@/, ''),
      agent: (m.agent || 'ultron').trim(),
      intent: m.intent || DEFAULT_INTENT,
      unread_only: !!m.unread,
      folder: m.folder || '',
      category: m.category || 'SPEDA-Seen',
      max_results: m.max || 10,
    },
    pairedItem: { item: 0 },
  });
});
// An empty list returns no items, which stops the branch harmlessly.
return out;

const store = $getWorkflowStaticData('global');
const broken = store.broken || {};
const cfg = $('Domain list').all();
const out = [];

$input.all().forEach((item, i) => {
  const res = item.json || {};
  const conf = (cfg[i] && cfg[i].json) || {};
  const id = conf.domain || ('#' + i);
  const status = res.status || 'error';

  // Watch health, EDGE-triggered per domain: a revoked Microsoft token makes
  // every rule blind at once, and at a 10-minute cadence that would be 144
  // identical pushes a day. One on the transition is enough.
  if (status !== 'ok') {
    if (!broken[id]) {
      broken[id] = true;
      out.push({ json: {
        alert: true, domain: id, agent: conf.agent || 'ultron',
        detail: res.detail || res.message || status,
        count: 0, message_ids: [], messages: [], intent: '',
      }, pairedItem: { item: i } });
    }
    return;
  }
  broken[id] = false;

  // The normal path: nothing arrived. No items = branch stops = no turn.
  if (!res.count) { return; }

  out.push({ json: {
    alert: false,
    domain: id,
    agent: conf.agent || 'ultron',
    intent: conf.intent || '',
    count: res.count,
    message_ids: res.message_ids || [],
    messages: res.messages || [],
    category: conf.category || 'SPEDA-Seen',
  }, pairedItem: { item: i } });
});

store.broken = broken;
return out;
